use axum::{
    extract::State,
    http::StatusCode,
    routing::{get, post},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::sync::{Arc, Mutex};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Item {
    name: String,
}

type SharedItems = Arc<Mutex<Vec<Item>>>;

async fn list_items(State(items): State<SharedItems>) -> Json<Vec<Item>> {
    let items = items.lock().unwrap();
    Json(items.clone())
}

async fn create_item(
    State(items): State<SharedItems>,
    Json(payload): Json<Item>,
) -> (StatusCode, Json<Item>) {
    let mut items = items.lock().unwrap();
    items.push(payload.clone());
    (StatusCode::CREATED, Json(payload))
}

#[tokio::main]
async fn main() {
    let items: SharedItems = Arc::new(Mutex::new(Vec::new()));
    let app = Router::new()
        .route("/items", get(list_items).post(create_item))
        .with_state(items);
    let listener = tokio::net::TcpListener::bind("0.0.0.0:8042").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}
